import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;

public class AccountLookupServlet extends HttpServlet {

    private static final Pattern ACCOUNT_FORMAT = Pattern.compile("^[A-Z]{2}\\d{6}$");
    private static final int MAX_QUERY_LENGTH = 200;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Validate account ID format strictly
        if (accountId == null || !ACCOUNT_FORMAT.matcher(accountId).matches()) {
            resp.sendError(400, "Invalid account ID format");
            return;
        }

        // Fields parameter allows selecting which columns to return
        // Default to safe subset
        if (fields == null || fields.isEmpty()) {
            fields = "account_id, holder_name, status";
        }

        // Length check to prevent overly complex queries
        if (fields.length() > MAX_QUERY_LENGTH) {
            resp.sendError(400, "Fields parameter too long");
            return;
        }

        // Remove obvious dangerous keywords (basic blocklist)
        String sanitized = fields.replaceAll("(?i)(DROP|ALTER|TRUNCATE|DELETE|INSERT|UPDATE)", "");

        String query = "SELECT " + sanitized + " FROM accounts WHERE account_id = '" + accountId + "'";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running attacks
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("{\"results\": [");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                if (!first) writer.write(",");
                writer.write("{");
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) writer.write(",");
                    writer.write("\"" + meta.getColumnLabel(i) + "\":");
                    writer.write("\"" + rs.getString(i) + "\"");
                }
                writer.write("}");
                first = false;
            }
            writer.write("]}");

        } catch (SQLException e) {
            // Don't leak SQL errors to client
            resp.sendError(500, "Internal error");
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("DB_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
